// Rusted Steel - brushed steel eaten by rust patches, with pitting, a dark
// corrosion front and rust stains running along v. Parametric (u,v), static.
//
// The rust is a threshold of a periodic fractal noise; its crust is raised
// (painted relief from the slope of the rust mask, as in Porous Bone) and
// pitted by small Voronoi craters.
// SEAM-FREE: every noise has whole numbers of cells per turn, so patches and
// streaks close up across u = 0/1 and v = 0/1. Twisted gluing (Klein
// bottle, Moebius band): set MIRROR_V to 1.0.
// Dock colors: u_col1 = steel, u_col2 = rust.

const float PATCHES_U = 5.0;   // rust patches around u (whole number) [2 .. 12]
const float PATCHES_V = 4.0;   // rust patches around v (whole number) [2 .. 12]
const float COVER     = 0.45;  // share of the surface eaten by rust [0 .. 1]
const float CRUST     = 1.0;   // raised rust crust (painted relief) [0 .. 2]
const float PITS      = 0.45;   // pitting inside the rust           [0 .. 1]
const float STAINS    = 0.5;   // rust stains on the steel          [0 .. 1]
const float BRUSH     = 0.5;   // brushing streaks of the steel     [0 .. 1]
const float MIRROR_U  = 0.0;   // 1 = fold u
const float MIRROR_V  = 0.0;   // 1 = fold v (Klein bottle, Moebius band)

// ---- seam-free toolkit: every grid has a whole number of cells per turn and
// ---- every cell index is wrapped, so the pattern repeats exactly at u, v = 0/1
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);   // 0 -> 0.5 -> 0: equal at both ends
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// random value of cell c, wrapped into the period n (negative indices too):
// the same cell one turn away gets the same value.
// NB: helper functions here return float/vecN only -- the per-mesh renamer of
// the engine recognizes those return types, not ivec2.
float cellHash(ivec2 c, ivec2 n, int salt) {
    ivec2 w = ivec2(mod(vec2(c), vec2(n)));
    uint h = uint(w.x) * 0x8da6b343u + uint(w.y) * 0xd8163841u + uint(salt) * 0xcb1ab31fu;
    h ^= h >> 15; h *= 0x2c1b3c6du;
    h ^= h >> 12; h *= 0x297a2d39u;
    h ^= h >> 15;
    return float(h >> 8) * (1.0 / 16777216.0);
}

vec2 cellHash2(ivec2 c, ivec2 n, int salt) {
    return vec2(cellHash(c, n, salt), cellHash(c, n, salt + 101));
}

// value noise with a period of n cells; uv in turns (0..1 = one turn)
float pnoise(vec2 uv, ivec2 n, int salt) {
    vec2 p = uv * vec2(n);
    ivec2 i = ivec2(floor(p));
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = cellHash(i, n, salt);
    float b = cellHash(i + ivec2(1, 0), n, salt);
    float c = cellHash(i + ivec2(0, 1), n, salt);
    float d = cellHash(i + ivec2(1, 1), n, salt);
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// fractal sum: each octave doubles the cells, so it stays periodic
float pfbm(vec2 uv, ivec2 n, int octaves, int salt) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int o = 0; o < 6; o++) {
        if (o >= octaves) break;
        sum += amp * pnoise(uv, n, salt + 17 * o);
        norm += amp;
        amp *= 0.5;
        n *= 2;
    }
    return sum / norm;
}

// Voronoi on a grid of n cells per turn (p in cells). Returns
//   x = distance to the nearest point, y = distance to the nearest border,
//   z = random id of the nearest cell.
// rel = p minus the nearest point; edgeDir = unit vector toward the nearest
// border (the downhill direction of anything that rises from the borders).
vec3 pvoronoi(vec2 p, ivec2 n, float jitter, int salt, out vec2 rel, out vec2 edgeDir) {
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    float best = 1.0e9;
    ivec2 bestCell = ivec2(0);
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 g = ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 dv = pt - fp;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = g; bestPt = pt; }
    }
    float border = 1.0e9;
    edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        ivec2 g = bestCell + ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - fp, dir);
        if (dist < border) { border = dist; edgeDir = dir; }
    }
    rel = fp - bestPt;
    return vec3(sqrt(best), border, cellHash(ip + bestCell, n, salt + 7));
}

float rustAmount(vec2 uv, ivec2 np, float th) {
    return smoothstep(th - 0.025, th + 0.025, pfbm(uv, np, 5, 3));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    ivec2 np = ivec2(int(PATCHES_U), int(PATCHES_V));
    float th = mix(0.66, 0.34, COVER);

    // rust mask and its slope (finite differences, all periodic samples)
    const float DU = 0.0012;
    float m  = pfbm(uv, np, 5, 3);
    float r  = smoothstep(th - 0.025, th + 0.025, m);
    float rx = rustAmount(uv + vec2(DU, 0.0), np, th);
    float ry = rustAmount(uv + vec2(0.0, DU), np, th);
    vec2 grad = vec2(rx - r, ry - r) / DU / float(max(np.x, np.y) * 8);

    // ---- steel: brushed streaks along u + broad anisotropic sheen
    float brush = pnoise(uv, ivec2(np.x * 3, np.y * 90), 7) - 0.5;
    float sheen = 0.5 + 0.5 * sin(TAU * (2.0 * uv.x + 0.6 * pnoise(uv, ivec2(2, 2), 9)));
    vec3 steel = u_col1 * (0.82 + 0.18 * sheen + 0.22 * BRUSH * brush);
    // light tarnish: broad, faint darker clouds on the bare metal
    steel *= 0.88 + 0.24 * pfbm(uv, np * 2, 3, 27);

    // stains: long streaks along v (few cells across v, many across u)
    float stain = smoothstep(0.55, 0.85, pnoise(uv, ivec2(np.x * 14, np.y), 51))
                * smoothstep(th - 0.2, th, m);
    steel = mix(steel, u_col2 * 0.75, STAINS * 0.6 * stain);

    // corrosion front: dark halo on the steel just outside the rust
    float fx = (m - (th - 0.035)) / 0.03;
    float front = exp(-fx * fx);
    steel *= 1.0 - 0.25 * front;

    // ---- rust: rough crust, color variation, pits
    float rough = pfbm(uv, np * 8, 4, 91);
    vec3 rustCol = mix(u_col2 * 0.45, u_col2 * 1.3, rough);
    rustCol = mix(rustCol, vec3(0.2, 0.08, 0.04), 0.35 * smoothstep(th + 0.05, th + 0.2, m));

    vec2 relP, dirP;
    vec3 pit = pvoronoi(uv * vec2(np * 12), np * 12, 0.9, 61, relP, dirP);
    float hasPit = step(1.0 - PITS * 0.6, pit.z);
    float pitMask = (1.0 - smoothstep(0.12, 0.28, pit.x)) * hasPit;
    rustCol *= 1.0 - 0.5 * pitMask;

    // painted relief of the crust: rim lit on one side, shaded on the other
    vec2 g2 = CRUST * grad + 0.4 * CRUST * r * (relP * pitMask);
    vec3 N = normalize(vec3(-g2, 1.0));
    vec3 L = normalize(vec3(-0.55, 0.65, 0.75));
    float light = dot(N, L) / L.z;

    vec3 col = mix(steel, rustCol, r) * light;
    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
